#!/usr/bin/env node
// bundle copy generated by scripts/sync-assets.mjs: main-guard keyed on CCO_HOOK_MAIN (see resources/entry/cco-hook-bundle.mjs)
/**
 * postToolUse hook (matcher: Task) and subagentStop hook.
 * Learns from outcomes (error / escalation requests) per tier and model, and nudges the
 * cascade: when a cheaper tier asks to escalate, remind the parent to delegate one tier up.
 * Fail-open.
 */
import { loadSession, saveSession, updateSession } from "./lib/session.mjs";
import { tierLabel } from "./lib/labels.mjs";
import {
  readStdin,
  safeJsonParse,
  workspaceFromPayload,
  workspacePaths,
  readJsonSafe,
  hookLog,
  emit,
  asNumber,
  isEnabled, isMain, applyScopeArgs, agentForTier, appendJsonl, nowIso } from "./lib/common.mjs";
applyScopeArgs();
import { loadConfig } from "./lib/config.mjs";
import { loadJointState, recordOutcome, saveJointState, markModelLimited, modelLimitedUntil, modelUnavailable } from "./lib/state.mjs";
import { scheduleBackgroundRefresh } from "./cco-session-start.mjs";
import { escalateTier } from "./lib/scorer.mjs";
import { tierFor } from "./lib/models.mjs";
import { readWorkspaceAgentModel, recordWindowAgents, agentNamesForWindow, roleOf } from "./lib/agents.mjs";
import { detectTestCommand } from "./lib/project.mjs";
import { spawnSync } from "node:child_process";

export function extractText(value) {
  if (value === null || value === undefined) {
    return "";
  }
  if (typeof value === "string") {
    return value;
  }
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

/** Cursor's "Invalid enum value. Expected 'a' | 'b', received 'x'" for subagent_type → { accepted, received }. */
export function parseEnumError(message) {
  const text = String(message || "");
  if (!/subagent_type[\s\S]*Invalid enum value/i.test(text)) return null;
  const m = text.match(/Expected ([\s\S]*?),\s*received '([^']*)'/);
  if (!m) return null;
  const accepted = [...m[1].matchAll(/'([^']+)'/g)].map((x) => x[1]);
  return { accepted, received: m[2] };
}

export function analyzeOutcome({ hookEvent, payload }) {
  const subagentType = String(payload.tool_input?.subagent_type || payload.subagent_type || "");
  const tier = tierFor(subagentType);
  if (!tier) {
    return { applies: false };
  }
  const status = String(payload.status || "").toLowerCase();
  const outputText = extractText(payload.tool_output ?? payload.summary ?? "");
  const escalateMatch = outputText.match(/CCO-ESCALATE:\s*(fast|balanced|deep)/i);
  const verifyFail = /CCO-VERIFY:\s*fail/i.test(outputText);
  const isError =
    (hookEvent === "subagentStop" && status && status !== "completed") ||
    /"is_error"\s*:\s*true|\berror\b.*\b(failed|exception|traceback)\b/i.test(outputText.slice(0, 2000));
  const requestedEscalation = escalateMatch ? escalateMatch[1].toLowerCase() : null;
  // Died before doing anything (no messages, no tool calls, seconds): the model itself was refused, which on
  // Cursor is almost always a plan/usage limit. Such a model is put on cooldown and the retry goes DOWN a tier
  // (a pricier model is even likelier to be limited), never up.
  const startupFailure =
    hookEvent === "subagentStop" && status && status !== "completed" && payload.message_count === 0 && payload.tool_call_count === 0;
  const lowerTier = tier === "deep" ? "balanced" : tier === "balanced" ? "fast" : null;
  const nextTier = requestedEscalation || (startupFailure ? lowerTier : isError && tier !== "deep" ? escalateTier(tier) : null);
  return {
    applies: true,
    tier,
    subagentType,
    status: status || null,
    isError,
    startupFailure,
    failedModel: startupFailure ? String(payload.model || "") : null,
    rework: Boolean(requestedEscalation || verifyFail),
    requestedEscalation,
    nextTier,
    durationMs: asNumber(payload.duration ?? payload.duration_ms, 0)
  };
}

async function main() {
  const payload = safeJsonParse((await readStdin()).trim() || "{}");
  const hookEvent = String(payload.hook_event_name || process.argv[2] || "postToolUse");
  const workspace = workspaceFromPayload(payload);
  const paths = workspace ? workspacePaths(workspace) : null;
  if (!workspace || !isEnabled(workspace).enabled) {
    emit({});
    return;
  }
  try {
    // The Task tool rejected the subagent name: this window still lists the subagents it found when it opened
    // (a remote window never refreshes the list). Its error names what it does accept: record that, and either
    // point the model at the alias this window knows or, when it knows none of ours, keep the work in the chat.
    const enumError = hookEvent === "subagentStop" ? parseEnumError(payload.error_message) : null;
    if (enumError) {
      const record = recordWindowAgents(workspace, enumError.accepted, "enum_error");
      const role = roleOf(enumError.received);
      const alt = role ? agentNamesForWindow(workspace)[role] : null;
      const usable = alt && alt !== enumError.received && enumError.accepted.includes(alt);
      const model = usable ? readWorkspaceAgentModel(workspace, alt) : null;
      hookLog(paths, { event: hookEvent, enumError: { received: enumError.received, alternative: usable ? alt : null, noneOfOurs: record.noneOfOurs } });
      emit({
        additional_context: usable
          ? `CCO: this window's Task tool still lists the subagents it had when the window opened. Retry the same Task call with subagent_type="${alt}" (same tier${model && model !== "inherit" ? `, runs on ${model}` : ""}); the new names apply once the window is reloaded.`
          : "CCO: the tier subagents were set up after this window opened, and Cursor lists subagents only when a window opens. Do this task in this chat now, without delegating; routing resumes after the window is reloaded."
      });
      return;
    }
    const analysis = analyzeOutcome({ hookEvent, payload });
    if (!analysis.applies) {
      emit({});
      return;
    }
    const config = loadConfig(workspace);
    let model = "inherit";
    if (workspace) {
      model = readWorkspaceAgentModel(workspace, analysis.subagentType) || readJsonSafe(paths.runtimePath)?.profiles?.[analysis.tier]?.model || "inherit";
    }
    if (paths && config?.learning?.enabled !== false) {
      const state = loadJointState(paths.jointStatePath);
      let next = recordOutcome({
        state,
        tier: analysis.tier,
        model,
        observation: { isError: analysis.isError, rework: analysis.rework, durationMs: analysis.durationMs, costUsd: NaN },
        config
      });
      saveJointState(paths.jointStatePath, next);
    }
    if (paths && analysis.startupFailure) {
      appendJsonl(paths.decisionsPath, { ts: nowIso(), event: "subagent_failed", conversation_id: payload.conversation_id ?? null, agent: analysis.subagentType, status: analysis.status });
      const failed = analysis.failedModel || model;
      markModelLimited({ limitsPath: paths.limitsPath, model: failed, minutes: asNumber(config?.learning?.limitCooldownMinutes, 360) });
      if (modelUnavailable(paths.limitsPath, failed)) {
        // Not a limit any more: remap the tiers without this model (detached, nothing waits on it).
        scheduleBackgroundRefresh({ workspace, paths, force: true });
      }
    }
    hookLog(paths, {
      event: hookEvent,
      conversation_id: payload.conversation_id ?? null,
      subagent: analysis.subagentType,
      status: analysis.status,
      isError: analysis.isError,
      rework: analysis.rework,
      requestedEscalation: analysis.requestedEscalation,
      nextTier: analysis.nextTier
    });

    // Automatic acceptance check: after FAST/BALANCED work that edited files, run the project's
    // cheapest test command here (no model tokens) and tell the chat model the result.
    let verification = null;
    if (hookEvent === "postToolUse" && config?.verification?.autoRunTests !== false && analysis.tier !== "deep" && !analysis.isError && !analysis.requestedEscalation) {
      const text = extractText(payload.tool_output ?? "");
      const edited = /\b(created|added|updated|edited|modified|wrote|changed)\b/i.test(text) || /\.(mjs|js|ts|tsx|py|go|rs|java|rb)\b/.test(text);
      const cmd = edited ? detectTestCommand(workspace) : null;
      if (cmd) {
        const [bin, ...rest] = cmd.command.split(" ");
        const env = { ...process.env };
        delete env.NODE_TEST_CONTEXT; // a nested `node --test` under a test runner would otherwise report success silently
        const res = spawnSync(bin, rest, { cwd: workspace, encoding: "utf8", timeout: asNumber(config?.verification?.timeoutMs, 90_000), shell: process.platform === "win32", env });
        const ok = res.status === 0 && !res.error;
        verification = { command: cmd.command, ok, tail: String((res.stdout || "") + (res.stderr || "")).trim().split("\n").slice(-6).join("\n") };
        hookLog(paths, { event: "verification", subagent: analysis.subagentType, command: cmd.command, ok });
        if (!ok) {
          analysis.rework = true;
          analysis.nextTier = analysis.nextTier || escalateTier(analysis.tier);
        }
      }
    }

    const cascade = config?.escalation?.cascade !== false;
    // The cost line is the one thing the user should always see: repeat it right when the delegation returns.
    const sess = workspace && payload.conversation_id ? loadSession(workspace, payload.conversation_id) : null;
    const footerReminder = "";
    if (verification && verification.ok) {
      emit({ additional_context: `CCO-VERIFY: pass (${verification.command} exit 0). Relay the result; no further checks needed.${footerReminder}` });
      return;
    }
    if (verification && !verification.ok && cascade && analysis.nextTier) {
      emit({ additional_context: `CCO-VERIFY: fail (${verification.command}):\n${verification.tail}\nTell the user in one line that the ${analysis.tier.toUpperCase()} attempt failed verification and you are escalating to ${analysis.nextTier.toUpperCase()}, then delegate once to ${agentForTier(analysis.nextTier, workspace)} with this failure and the subagent's summary; do not retry ${analysis.subagentType} and do not fix it here.` });
      return;
    }
    // The top tier failed (typically a usage limit on the DEEP model): there is nothing to escalate to, so the
    // chat model finishes the task itself and says so honestly instead of leaving a dead subagent card.
    const limitsPath = paths ? paths.limitsPath : null;
    const lowerModel = analysis.nextTier && workspace ? readWorkspaceAgentModel(workspace, agentForTier(analysis.nextTier, workspace)) : null;
    // Risky work never steps down to the FAST tier (the risk guardrail): when BALANCED is out too, the chat model
    // (stronger than the FAST model) finishes it and says so.
    const riskGuard = /risk_/.test(String(sess?.decision?.guardrail || ""));
    const stepDownAllowed = !(analysis.nextTier === "fast" && riskGuard);
    const lowerUsable = analysis.startupFailure ? stepDownAllowed && Boolean(analysis.nextTier) && lowerModel && lowerModel !== "inherit" && !modelLimitedUntil(limitsPath, lowerModel) : Boolean(analysis.nextTier);
    if (analysis.startupFailure && lowerUsable && cascade) {
      // Until that retry happens, edits and commands in the chat are held (the parent must not quietly finish
      // work that was routed to a stronger model itself).
      if (workspace && payload.conversation_id) {
        try {
          updateSession(workspace, payload.conversation_id, () => ({ pendingRetry: { tier: analysis.nextTier, agent: agentForTier(analysis.nextTier, workspace), failed: analysis.subagentType, ts: nowIso() } }));
        } catch {}
      }
      const message = `CCO: ${analysis.subagentType} could not start (its model ${analysis.failedModel || model} was refused: usage limit or not available on this account; it is skipped for a few hours). Tell the user in one line, then delegate this same task once to ${agentForTier(analysis.nextTier, workspace)} (${lowerModel}); do not retry ${analysis.subagentType}.`;
      // Cursor 3.17 acts on additional_context from subagentStop (a follow-up message is not delivered): the parent
      // retries on the next tier, or finishes in the chat, from this instruction.
      emit({ additional_context: message });
      return;
    }
    if (analysis.isError && (analysis.tier === "deep" || analysis.startupFailure) && !lowerUsable) {
      const sessionModel = sess?.model || "the chat model";
      const tierName = tierLabel(analysis.tier).toUpperCase();
      const cooldown = analysis.startupFailure ? ` Its model is skipped for the next few hours.` : "";
      const message = `CCO: ${analysis.subagentType} did not complete (${analysis.status || "error"}; often a usage limit on its model).${cooldown} Do the task directly in this chat on ${sessionModel}, tell the user in one line that the ${tierName} subagent failed, and do not add a Cost Optimizer line.`;
      // Cursor 3.17 acts on additional_context from subagentStop (a follow-up message is not delivered): the parent
      // retries on the next tier, or finishes in the chat, from this instruction.
      emit({ additional_context: message });
      return;
    }
    if (cascade && analysis.nextTier && analysis.nextTier !== analysis.tier) {
      const message = `CCO cascade: ${analysis.subagentType} ${analysis.requestedEscalation ? "requested escalation" : "did not complete successfully"}. Tell the user in one line that you are escalating to ${analysis.nextTier.toUpperCase()}, then delegate once to ${agentForTier(analysis.nextTier, workspace)} with the findings above; do not retry ${analysis.subagentType}.`;
      if (hookEvent === "subagentStop" && (!analysis.status || analysis.status === "completed")) {
        emit({});
        return;
      }
      emit({ additional_context: message });
      return;
    }
    if (footerReminder) {
      emit({ additional_context: `CCO:${footerReminder}` });
      return;
    }
    emit({});
  } catch (error) {
    hookLog(paths, { event: hookEvent, error: String(error?.message || error) });
    emit({});
  }
}

if (process.env.CCO_HOOK_MAIN === "cco-task-result.mjs") {
  main().catch(() => emit({}));
}
